/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const {
        selectionProps: {
            selectedRowIds,
            allRowsSelected,
            exceptedRowIds
        },
        rowDefinitions: {
            rows
        },
    } = api.data.controller;

    let sysIds;

    const getCascadeText = (numRecords, content) =>
        helpers.translateSync(
            'Deleting these {0} record(s) will result in automatic deletion of {1} related record(s).',
            `${numRecords}`,
            `${content.totalCount}`
        );

    const getDbViewCascadeText = (numRecords, content) =>
        helpers.translateSync(
            'Deleting these {0} database view record(s) will result in automatic deletion of {1} related record(s).',
            `${numRecords}`,
            `${content.totalCount}`
        );

    const getRecordText = numRecords =>
        helpers.translateSync('Delete {0} record(s)?', `${numRecords}`);

    const getDbViewRecordText = numRecords =>
        helpers.translateSync('Delete {0} database view record(s)?', `${numRecords}`);

    const glideCascadeProperty = 'glide.ui.confirm_cascade_delete';
    const isDBView = api.data.controller.isDBView;
    const isCascadeDeleteConfirmed = api.data.get_system_properties_values.output.properties[glideCascadeProperty];

    if (allRowsSelected) {
        const allSysIds = rows.map((row) => row.key);
        const selectedRecordsOnPage = allSysIds.filter(
            (sysId) => !exceptedRowIds.includes(sysId)
        );
        sysIds = selectedRecordsOnPage;
    } else {
        sysIds = selectedRowIds;
    }

    const selectedRecords = sysIds;
    const content = api.data.cascade_delete_popup_query.output.data.GlideCascadeDelete_Query.result;
    const cascadeRecordsLen = content.cascadeRecords.length;

    const noCascade =
        (isCascadeDeleteConfirmed !== true && isCascadeDeleteConfirmed !== 'true') ||
        isCascadeDeleteConfirmed === null ||
        !cascadeRecordsLen ||
        api.data.controller.current.table === 'sys_attachment';

    const cascadeMsg = isDBView ?
        getDbViewCascadeText(selectedRecords.length, content) :
        getCascadeText(cascadeRecordsLen, content);

    const noCascadeMsg = isDBView ?
        getDbViewRecordText(selectedRecords.length) :
        getRecordText(selectedRecords.length);

    const deleteMessage = noCascade ? noCascadeMsg : cascadeMsg;

    return deleteMessage;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const prop = 'glide.ui.confirm_cascade_delete';
    const isDeleteConfirmed = api.data.get_system_properties_values.output.properties[prop];
    const content = api.data.cascade_delete_popup_query.output.data.GlideCascadeDelete_Query.result;
    const cascadeRecordsLen = content.cascadeRecords.length;

    const noCascade =
        (isDeleteConfirmed !== true && isDeleteConfirmed !== 'true') ||
        isDeleteConfirmed === null ||
        !cascadeRecordsLen || api.data.controller.current.table === 'sys_attachment';;

    return noCascade;
}

